import{_ as r,o as a,c as o,a2 as n}from"./chunks/framework.BN62cPSf.js";const c=JSON.parse('{"title":"附 B　常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"appendix/b-faq.md","filePath":"appendix/b-faq.md","lastUpdated":1793337833000}'),s={name:"appendix/b-faq.md"};function e(p,t,g,i,l,d){return a(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="附-b-常见问题" tabindex="-1">附 B　常见问题 <a class="header-anchor" href="#附-b-常见问题" aria-label="Permalink to &quot;附 B　常见问题&quot;">​</a></h1><p>问题都是真实会被问到的，答案短，指向正文哪一节。</p><h2 id="关于开始" tabindex="-1">关于开始 <a class="header-anchor" href="#关于开始" aria-label="Permalink to &quot;关于开始&quot;">​</a></h2><p><strong>我一米七、八十公斤，从哪儿开始？</strong> 先算你的线（2.3），再从 5.2 的第一周做起——第一周只记录，不改。不改的那一周不是浪费时间，是让你知道自己现在吃多少。不知道起点就没法设缺口。</p><p><strong>可以一上来就砍一千千卡吗？</strong> 不行。缺口越大，掉的越不全是脂肪，掉的会有一部分肌肉，而且坚持不到第四周。缺口 500 是常规做法，上限 1000 也要在医生指导下。</p><p><strong>需要买体脂秤、食物秤、手环吗？</strong> 体脂秤有点用，看趋势不看单次读数；食物秤只在前两周用，为了校准你的眼睛，之后扔掉；手环的步数可用，热量消耗数字偏差大，别拿它当饭吃。</p><p><strong>不吃早饭行不行？</strong> 总热量一样的话，吃不吃早饭对减重没有决定性差别。但如果你不吃早饭会在下午崩掉，那就吃。看的是全天的账，不是某一顿。</p><h2 id="关于吃" tabindex="-1">关于吃 <a class="header-anchor" href="#关于吃" aria-label="Permalink to &quot;关于吃&quot;">​</a></h2><p><strong>米饭到底能不能吃？</strong> 能。碳水不是敌人，总量才是。指南给的底线是每天 130 克碳水（2.4），低于这个数不是减脂，是折腾身体。</p><p><strong>晚上八点以后吃东西会胖吗？</strong> 胖不胖看全天总热量，不看你几点吃。但夜里的进食大多是无意识进食——刷手机顺手抓一把，这部分几乎从不被记录。</p><p><strong>无糖可乐能喝吗？</strong> 热量可以按零算，但别把它当成减肥工具。WHO 2023 年的意见是不建议把非糖甜味剂当作控制体重的手段（1.7）。</p><p><strong>水果那么甜，减脂期要不要戒？</strong> 不用戒，限量。一天两份，按附 A 的水果表换算，香蕉荔枝那份小一些。</p><p><strong>代餐、酵素、减肥茶有用吗？</strong> 代餐的本质是把一顿饭的热量锁死，能管用，但你得一辈子吃代餐，这不现实。酵素和大部分减肥茶没有可靠证据（1.10）。</p><p><strong>放纵餐要不要安排？</strong> 能不做就不做（3.8）。想吃就安排在可预期的一顿，吃完接着记，别把“今天破戒了”当成整周放弃的理由。</p><p><strong>16+8 能不能用？</strong> 能用，但它不比普通限热量更有效。TREAT 试验里两组减重没有显著差别（1.11）。它的真正好处是少吃一顿好执行，不是有什么代谢魔法。</p><h2 id="关于练" tabindex="-1">关于练 <a class="header-anchor" href="#关于练" aria-label="Permalink to &quot;关于练&quot;">​</a></h2><p><strong>我只想瘦肚子，练腹肌行不行？</strong> 不行。局部减脂在实验里没被证实过（1.4）。卷腹能把腹肌练厚，但它上面那层脂肪得靠全身热量缺口掉。</p><p><strong>跑步会不会把腿跑粗？</strong> 不会（1.5）。跑完觉得腿胀，那是肌肉充血和水肿，几小时就消。真正让腿变粗的是力量训练加吃超。</p><p><strong>大基数能不能直接跑？</strong> 先别跑（4.1）。走路、游泳、骑车、椭圆机都可以，等 BMI 降到 28 以下、膝盖没有不适再加跑。</p><p><strong>必须去健身房吗？</strong> 不用。4.4 那六个自重动作，在家、每次十分钟就能开始。抗阻的意义是保住肌肉，不是练出线条。</p><p><strong>每周要练多少？</strong> 有氧每周 150～300 分钟，抗阻每周 2～3 次（4.2）。这两个数字是下限，不是目标。</p><h2 id="关于数字" tabindex="-1">关于数字 <a class="header-anchor" href="#关于数字" aria-label="Permalink to &quot;关于数字&quot;">​</a></h2><p><strong>体重一天涨了两斤，是不是胖了？</strong> 不是（1.8）。一天里体重的波动主要来自水、盐、糖原和肠道内容物。看一周的平均值。</p><p><strong>我的代谢是不是坏了？</strong> 大多数说“代谢慢”的人，记录出来的摄入比实际低（1.9、2.5）。先老老实实记两周再判断。</p><p><strong>三周没动了，是平台期吗？</strong> 三周平均不动才算（6.1）。一两周不动大多还是水。真卡住了按 6.3 的七步排查。</p><p><strong>要天天称体重吗？</strong> 建议天天称，看周平均。怕数字影响心情的，改成每周固定三次，但别一个月才称一次——那样等发现的时候已经涨了三公斤。</p><h2 id="关于药和手术" tabindex="-1">关于药和手术 <a class="header-anchor" href="#关于药和手术" aria-label="Permalink to &quot;关于药和手术&quot;">​</a></h2><p><strong>司美格鲁肽、替尔泊肽我能用吗？</strong> 有门槛（8.3）：司美格鲁肽 BMI ≥30，或 27～30 且有合并症；替尔泊肽 BMI ≥28，或 ≥24 且有合并症。必须由医生开，有甲状腺髓样癌个人史或家族史、MEN2 的人不能用。有进食障碍史的人不能用。</p><p><strong>打了针是不是就不用管吃了？</strong> 不是。停药后体重会不同程度回来：STEP-1 的延伸研究里，停药一年回来约三分之二（8.3）。</p><p><strong>减重手术是不是一劳永逸？</strong> 不是。术后一样要跟饮食和运动，指南把“比最低点反弹超过 15%”定义为体重反弹。</p><h2 id="关于这本书" tabindex="-1">关于这本书 <a class="header-anchor" href="#关于这本书" aria-label="Permalink to &quot;关于这本书&quot;">​</a></h2><p><strong>这些数据你自己测过吗？</strong> 没有。除体重之外，我一项都没测——体成分、代谢指标、训练量都没有。正文里标 C 的地方就是这一类，别当结论看。</p><p><strong>为什么每条后面都有字母？</strong> 那是证据等级（见开头）。A 是官方文件、综述、大样本试验，B 是单项试验或队列，C 是机制推断和个人经验。标 C 的意思不是“我认为”，是“这条经不起拿去跟人吵架”。</p><p><strong>发现有错怎么办？</strong> 去仓库提 issue，写清哪一节、原文是什么、依据在哪。核到一手来源我就改，改动记在 CHANGELOG 里。</p>',34)])])}const _=r(s,[["render",e]]);export{c as __pageData,_ as default};
